CREATE TABLE sfi_result(seq INTEGER,label TEXT,value INTEGER); INSERT INTO sfi_result SELECT 1,'before',sum(c65) FROM t1; BEGIN; UPDATE t1 SET c65=c65+1 WHERE c00=1000; ROLLBACK; INSERT INTO sfi_result SELECT 2,'after_rollback',sum(c65) FROM t1; BEGIN; UPDATE t1 SET c65=c65+1 WHERE c00=1000; INSERT INTO sfi_result SELECT 3,'after_update',sum(c65) FROM t1; COMMIT; UPDATE t1 SET c65=c65-1 WHERE c00=1000; INSERT INTO sfi_result SELECT 4,'restored',sum(c65) FROM t1;